    source('src-eymorg-controller-review', 'Spock’s Brain: Synopsis', 'Bernd Schneider / Ex Astris Scientia', 'https://www.ex-astris-scientia.org/episodes/tos3.htm', 'secondary_tv_episode_reference_indexed', 'Spock’s Brain synopsis only read', 'The Eymorg use a stolen biological brain as Controller and lack technical understanding.', 'This is not automatically an independent AI sovereign. Underground infrastructure alone does not specify food allocation or its labor requirements.'),
