    decision('c0384', 'boundary_case', 'Exo III’s surviving android machinery does not establish a supported extant human community.', ['src-exo-iii-reference'], analysis='Dead creators do not enter a leisure denominator, and later research or human-derived copies do not establish a general economic constitution.', follow_up='Keep as a machine-survival/personhood comparison.'),
    decision('c0385', 'needs_evidence', 'The Eymorg’s brain-controlled infrastructure does not have verified household allocation in the short check.', ['src-eymorg-controller-review'], analysis='A stolen living brain performs a real controlling function; it must not be relabeled as an external autonomous AI merely because it interfaces with machinery.', follow_up='Skip transcript reconstruction; reopen only for a clear provision account.'),
    decision('c0386', 'included', 'The Custodian explicitly provides residents’ needs while accepting resident commands, with the alien-person proxy and uncertain governance disclosed.', a, society_id='aldea-custodian-provision'),
